import { useState, useMemo, useRef } from 'react';
import createDeferred from '@kne/create-deferred';
import { useContext, usePreset } from '@kne/global-context';
import useRefCallback from '@kne/use-ref-callback';
import { App } from 'antd';
import uniqueId from 'lodash/uniqueId';
import { createIntl } from '@kne/react-intl';
import computedAccept from './computedAccept';
import { uploadFile } from './uploadFile';
import { useFileSystemContext } from '../FileSystem/FileSystemContext';

const formatAcceptLabel = accept => {
  if (!accept) {
    return '';
  }
  const acceptList = Array.isArray(accept) ? accept : accept.split(',');
  return acceptList
    .map(item => item.trim().replace(/^\./, ''))
    .filter(Boolean)
    .join(', ');
};

const useFileUpload = p => {
  const { locale } = useContext();
  const { formatMessage } = createIntl({ locale, namespace: 'react-file' });
  const fileSystem = useFileSystemContext();
  const { multiple, fileSize, maxLength, value, concurrentCount, accept, onAdd, onError, onSave, onChange, onUpload, directory } = Object.assign(
    {},
    {
      concurrentCount: 1,
      value: [],
      fileSize: 100,
      maxLength: 10,
      multiple: true,
      accept: null
    },
    p
  );

  // 未显式传 directory 时，自动使用 FileSystem 当前上传目录（含分栏展开路径）
  const resolvedDirectory = directory !== undefined ? directory : fileSystem?.uploadPath;

  const { apis } = usePreset();
  const { message } = App.useApp();
  const [uploadingList, setUploadingList] = useState([]);
  const deferred = useMemo(() => {
    return createDeferred(concurrentCount);
  }, [concurrentCount]);
  const acceptLabel = useMemo(() => formatAcceptLabel(accept), [accept]);
  const directoryRef = useRef(resolvedDirectory);
  directoryRef.current = resolvedDirectory;

  const onFileSelected = useRefCallback(async fileList => {
    const allowCount = maxLength - value.length;
    if (!(maxLength === 1 || multiple !== true) && fileList.length > allowCount) {
      message.error(formatMessage({ id: 'FileUpload.maxLengthError' }, { maxLength }));
      return;
    }
    await Promise.allSettled(
      fileList.map(async file => {
        if (!computedAccept(file, accept)) {
          message.error(
            formatMessage(
              { id: 'FileUpload.acceptError' },
              {
                filename: file.name,
                accept: acceptLabel
              }
            )
          );
          return;
        }
        if (file.size > fileSize * 1024 * 1024) {
          message.error(formatMessage({ id: 'FileUpload.fileSizeError' }, { filename: file.name, fileSize }));
          return;
        }
        const uuid = uniqueId();
        const catchError = e => {
          const errMsg =
            e.message ||
            formatMessage(
              { id: 'FileUpload.uploadError' },
              {
                filename: file.name,
                error: e.message ? ':' + e.message : ''
              }
            );
          message.error(errMsg);
          onError && onError({ file, error: e, errMsg });
          setUploadingList(list => {
            const newList = list.slice(0);
            const index = newList.findIndex(item => item.uuid === uuid);
            index > -1 && newList.splice(index, 1);
            return newList;
          });
        };

        try {
          if (maxLength === 1 || multiple !== true) {
            setUploadingList([
              {
                uuid,
                type: 'uploading',
                filename: file.name
              }
            ]);
          } else {
            setUploadingList(list => {
              const newList = list.slice(0);
              newList.unshift({
                uuid,
                type: 'uploading',
                filename: file.name
              });
              return newList;
            });
          }
          onAdd && (await Promise.resolve(onAdd(file)));
          const { data } = await deferred(() =>
            uploadFile({
              file,
              directory: directoryRef.current,
              onUpload,
              apis
            })
          );

          if (data.code !== 0) {
            catchError(
              new Error(
                formatMessage(
                  { id: 'FileUpload.uploadError' },
                  {
                    filename: file.name,
                    error: data.msg ? ':' + data.msg : ''
                  }
                )
              )
            );
            return;
          }

          const outputData = onSave
            ? await Promise.resolve(onSave(data, file, uuid))
            : Object.assign({}, data.data, {
                filename: data.data.filename || data.data.originName || file.name,
                id: data.data.id,
                uuid
              });

          setUploadingList(list => {
            const newList = list.slice(0);
            const index = newList.findIndex(item => item.uuid === uuid);
            index > -1 && newList.splice(index, 1);
            return newList;
          });
          if (maxLength === 1 || multiple !== true) {
            onChange([outputData]);
          } else {
            onChange(list => {
              const newList = (list || []).slice(0);
              if (newList.length >= maxLength) {
                return newList;
              }
              newList.push(outputData);
              return newList;
            });
          }
        } catch (e) {
          catchError(e);
        }
      })
    );
  });

  return {
    fileList: uploadingList,
    onFileSelected
  };
};

export default useFileUpload;
